sp_widget.css:
.cr-head{background:linear-gradient(135deg,#0f5c6b 0%,#17879c 100%);color:#fff;border-radius:14px;padding:24px 28px;margin-bottom:20px}
.cr-head h1{margin:0 0 4px;font-size:24px;font-weight:600;color:#fff}
.cr-head p{margin:0;font-size:13.5px;opacity:.85;color:#fff}
.cr-card{background:#fff;border:1px solid #e3e8ee;border-radius:12px;box-shadow:0 1px 2px rgba(16,32,48,.04);padding:18px;margin-bottom:16px}
.cr-card h3{margin:0 0 2px;font-size:15.5px;font-weight:600;color:#16232e}
.cr-sub{font-size:12.5px;color:#7a8b99;margin:0 0 14px}
.cr-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:14px;margin-bottom:18px}
.cr-stat{background:#fff;border:1px solid #e3e8ee;border-radius:12px;padding:16px 18px}
.cr-stat .v{font-size:26px;font-weight:600;color:#0f5c6b;line-height:1.15}
.cr-stat .k{font-size:11.5px;text-transform:uppercase;letter-spacing:.06em;color:#7a8b99;margin-top:2px}
.cr-btn{display:inline-block;background:#0f5c6b;color:#fff;border:0;border-radius:8px;padding:9px 16px;font-size:13px;font-weight:500;text-decoration:none;cursor:pointer}
.cr-btn:hover,.cr-btn:focus{background:#0d4e5b;color:#fff;text-decoration:none}
.cr-btn-ghost{background:#fff;color:#a13b32;border:1px solid #f0c9c5}
.cr-btn-ghost:hover{background:#fdecea;color:#a13b32}
.cr-btn-sm{padding:6px 12px;font-size:12px;border-radius:7px}
.cr-table{width:100%;border-collapse:separate;border-spacing:0;font-size:13.5px}
.cr-table th{text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:#7a8b99;font-weight:600;padding:8px 10px;border-bottom:1px solid #eef2f6;white-space:nowrap}
.cr-table td{padding:11px 10px;border-bottom:1px solid #f4f7fa;color:#33424f;vertical-align:middle}
.cr-table tr:last-child td{border-bottom:0}
.cr-table tbody tr:hover td{background:#fafcfd}
.cr-tag{font-size:11px;font-weight:600;letter-spacing:.04em;text-transform:uppercase;border-radius:999px;padding:3px 9px;display:inline-block}
.cr-tag.ok{background:#e7f5ec;color:#1e7a45}
.cr-tag.no{background:#f2f4f6;color:#7a8b99}
.cr-tag.hol{background:#fdecea;color:#a13b32}
.cr-tag.day{background:#e6f3f6;color:#0f5c6b}
.cr-chips{display:flex;flex-wrap:wrap;gap:6px}
.cr-chip{background:#f1f5f8;border:1px solid #e6ecf1;border-radius:8px;padding:5px 9px;font-size:11.5px;color:#3b4a56;white-space:nowrap}
.cr-chip b{font-weight:600;color:#16232e}
.cr-empty{color:#9aa9b6;font-size:13px;padding:14px 0}
@media(max-width:700px){.cr-table{display:block;overflow-x:auto;white-space:nowrap}}
.cal-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap}
.cal-legend{display:flex;align-items:center;gap:6px;font-size:12px;color:#7b8794;white-space:nowrap}
.cal-key{width:8px;height:8px;border-radius:50%;display:inline-block;margin-left:10px}
.cal-key.ok{background:#2f9e6b;margin-left:0}
.cal-key.no{background:#d9534f}
.cal-months{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:16px;margin-top:6px}
.cal-month{background:#fafbfc;border:1px solid #eceff2;border-radius:10px;padding:12px}
.cal-mlabel{font-size:11.5px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#13758a;margin-bottom:10px}
.cal-grid{display:flex;flex-wrap:wrap;gap:6px}
.cal-day{width:42px;padding:5px 0;text-align:center;background:#fff;border:1px solid #e3e8ec;border-radius:7px}
.cal-n{display:block;font-size:15px;font-weight:600;color:#22303c;line-height:1.1}
.cal-w{display:block;font-size:9.5px;letter-spacing:.04em;text-transform:uppercase;color:#8b98a5}
.cal-hols{margin-top:10px;border-top:1px dashed #e1e6ea;padding-top:8px}
.cal-hol{font-size:12px;color:#a13b32;display:flex;align-items:center;gap:6px;padding:2px 0}
.cal-hol .cal-key{margin:0}
.dash-grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(320px,1fr);gap:16px;align-items:start}
.dash-grid .cr-card{margin-bottom:0}
.dash-grid .cal-months{grid-template-columns:1fr;gap:12px}
.dash-grid .cal-day{width:38px}
.dash-grid .cal-month{padding:10px}
@media(max-width:991px){.dash-grid{grid-template-columns:1fr}}

sp_widget.script:
(function() {
  var CAR_TABLE = 'x_2203703_car_re_0_car';
  var RES_TABLE = 'x_2203703_car_re_0_reservation';
  var CAL_TABLE = 'x_2203703_car_re_0_cal_day';

  data.cars = [];
  data.total_cars = 0;
  data.available_cars = 0;
  data.active_reservations = 0;
  data.out_today = 0;
  data.business_days = [];
  data.holidays = [];
  data.calendar = [];
  data.months = [];
  data.today = '';
  data.err = '';

  function ymd(v) {
    if (!v) return '';
    return String(v).substring(0, 10);
  }

  try {
    var today = ymd(new GlideDateTime().getLocalDate().getValue());
    data.today = today;

    // reservations: today's rentals + next upcoming per car
    var byCar = {};
    var active = 0;
    var outToday = 0;
    var res = new GlideRecord(RES_TABLE);
    res.addQuery('state', 'reserved');
    res.addQuery('end_date', '>=', today);
    res.orderBy('start_date');
    res.query();
    while (res.next()) {
      active++;
      var s = ymd(res.getValue('start_date'));
      var e = ymd(res.getValue('end_date'));
      var carId = res.getValue('car');
      var onRent = (s && e && s <= today && e >= today) ? true : false;
      if (onRent) outToday++;
      if (!byCar[carId]) byCar[carId] = { onRent: false, next: '' };
      if (onRent) byCar[carId].onRent = true;
      if (!byCar[carId].next || s < byCar[carId].next) byCar[carId].next = s;
    }
    data.active_reservations = active;
    data.out_today = outToday;


    // out-of-service windows
    var oos = {};
    var uv = new GlideRecord('x_2203703_car_re_0_car_unavail');
    uv.addQuery('end_date', '>=', today);
    uv.query();
    while (uv.next()) {
      var uc = uv.getValue('car');
      if (!uc) continue;
      if (!oos[uc]) oos[uc] = [];
      oos[uc].push({ start: ymd(uv.getValue('start_date')), end: ymd(uv.getValue('end_date')) });
    }

    var free = 0;
    var car = new GlideRecord(CAR_TABLE);
    car.orderBy('name');
    car.query();
    while (car.next()) {
      var id = car.getUniqueValue();
      var inService = car.getValue('available') == '1';
      var b = byCar[id];
      var status = 'Available';
      var cls = 'ok';
      var covered = false;
      var w = oos[id];
      if (w) for (var wi = 0; wi < w.length; wi++) if (w[wi].start <= today && w[wi].end >= today) covered = true;
      if (!inService) { status = 'Out of service'; cls = 'no'; }
      else if (covered) { status = 'Out of service (dates)'; cls = 'no'; }
      else if (b && b.onRent) { status = 'On rent'; cls = 'no'; }
      else if (b && b.next) { status = 'Booked ' + b.next; cls = 'day'; }
      else { free++; }
      data.cars.push({
        name: car.getValue('name'),
        type: car.getDisplayValue('type'),
        seats: car.getValue('seating_capacity'),
        rent: car.getDisplayValue('rent') || '',
        available: inService,
        status: status,
        status_class: cls,
        next: (b && b.next) ? b.next : ''
      });
    }
    data.total_cars = data.cars.length;
    data.available_cars = free;

    var cal = new GlideRecord(CAL_TABLE);
    cal.addQuery('date', '>=', today);
    cal.orderBy('date');
    cal.query();
    while (cal.next()) {
      var entry = {
        date: ymd(cal.getValue('date')),
        type: cal.getValue('day_type'),
        label: cal.getValue('label') || '',
        cutoff: cal.getValue('cutoff_time') || ''
      };
      data.calendar.push(entry);
      if (entry.type == 'holiday') data.holidays.push(entry); else data.business_days.push(entry);
    }

    var MN = ['January','February','March','April','May','June','July','August','September','October','November','December'];
    var DW = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
    var mk = {};
    for (var i = 0; i < data.calendar.length; i++) {
      var d = data.calendar[i];
      var key = d.date.substring(0, 7);
      if (!mk[key]) {
        var mi = parseInt(key.substring(5, 7), 10) - 1;
        mk[key] = { label: MN[mi] + ' ' + key.substring(0, 4), days: [], holidays: [] };
      }
      var dow = DW[new Date(parseInt(d.date.substring(0, 4), 10), parseInt(d.date.substring(5, 7), 10) - 1, parseInt(d.date.substring(8, 10), 10), 12).getDay()];
      var item = {
        date: d.date,
        dnum: d.date.substring(8, 10),
        dow: dow,
        full: d.date,
        mday: d.date.substring(5, 7) + '/' + d.date.substring(8, 10),
        label: d.label,
        cutoff: d.cutoff || '15:00'
      };
      if (d.type == 'holiday') mk[key].holidays.push(item); else mk[key].days.push(item);
    }
    for (var k in mk) data.months.push(mk[k]);
  } catch (e) {
    data.err = String(e && e.message ? e.message : e);
    gs.error('Admin Console: ' + data.err);
  }
})();
